import{_ as l,a0 as d,w as n,s as r,I as t,x as i,a1 as o,A as e,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何在 Fedora Linux 上安裝 Discord | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Fedora Linux 上安裝 Discord | LCTT (202111) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Fedora Linux 上安裝 Discord | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Fedora Linux 上安裝 Discord | LCTT (202111) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202111/20211120 How to Install Discord on Fedora Linux","title":"如何在 Fedora Linux 上安裝 Discord","tag":"202111","desc":""},"relativePath":"202111/20211120 How to Install Discord on Fedora Linux.md","filePath":"[post].md"}'),u={name:"202111/20211120 How to Install Discord on Fedora Linux.md"};function h(c,s,g,k,f,b){const a=d("Link");return n(),r("div",null,[s[17]||(s[17]=t("h1",{id:"如何在-fedora-linux-上安裝-discord",tabindex:"-1"},[i("如何在 Fedora Linux 上安裝 Discord "),t("a",{class:"header-anchor",href:"#如何在-fedora-linux-上安裝-discord","aria-label":"Permalink to “如何在 Fedora Linux 上安裝 Discord”"},"​")],-1)),s[18]||(s[18]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/202111/27/115501g3oiuirvzk4nvu3k.jpg",alt:""})],-1)),t("p",null,[o(a,{href:"https://discord.com/"},{default:e(()=>[...s[0]||(s[0]=[i("Discord",-1)])]),_:1}),s[1]||(s[1]=i(" 是一個流行的消息收發應用，可用於文字和語音信息傳遞。",-1))]),s[19]||(s[19]=p('<p>它是一些社區的福音，可以幫助他們擴大項目，接觸更多的人，並維持一個粉絲和關注者的社區。而 Discord 最初是為遊戲玩家設計的，這很令人驚訝。</p><p>Discord 可用於各種平台，包括 Linux。在本教程中，我將引導你完成在 Fedora 中安裝 Discord 的步驟。</p><ul><li>使用 DNF 和 RPM Fusion 倉庫安裝 Discord</li><li>通過 Flatpak 安裝Discord</li></ul><p>Flatpak 軟件包是沙盒的，因此需要更多的磁盤空間和時間來啓動。然而，他們會相當快地更新到新的版本。</p><p>無論你想使用 Flatpak 還是 DNF，選擇權在你手上。我將向你展示這兩種方法。</p><blockquote><p>非 FOSS 警報！</p><p>Discord 並不是開源的。但由於他們提供了一個 Linux 客户端，而且許多 Linux 用户都依賴它，所以我們會在這裏介紹它。</p></blockquote><h3 id="方法-1-通過-rpm-fusion-倉庫安裝-discord" tabindex="-1">方法 1：通過 RPM Fusion 倉庫安裝 Discord <a class="header-anchor" href="#方法-1-通過-rpm-fusion-倉庫安裝-discord" aria-label="Permalink to “方法 1：通過 RPM Fusion 倉庫安裝 Discord”">​</a></h3><p>Discord 可以通過添加非自由的 RPM Fusion 倉庫來安裝，這是大多數 Fedora 用户的首選方法，因為更新很容易，而且應用的啓動速度比 Flatpak 版本快。</p><p>打開終端，使用下面的命令來添加 RPM-fusion 非自由倉庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install https://download1.rpmfusion.org/nonfree/fedora/rpmfusion-nonfree-release-$(rpm -E %fedora).noarch.rpm</span></span></code></pre></div><p>完成後，更新倉庫列表（應該不需要，但只是為了它）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf update</span></span></code></pre></div><p>然後通過 <code>dnf</code> 命令安裝 Discord，像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install discord</span></span></code></pre></div><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/11/install-discord-dnf.png?resize=800%2C525&amp;ssl=1" alt="Installing Discord using DNF"></p><p>如果被要求導入 GPG 密鑰，只要按 <code>Y</code> 就可以授權了。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/11/authorize-gpg-key-1.png?resize=800%2C573&amp;ssl=1" alt="Authorize GPG key"></p><p>這就完成了！現在你可以從應用菜單中啓動 Discord。你的登錄頁面將看起來像這樣：</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/11/Discord-2.png?resize=800%2C432&amp;ssl=1" alt="Launch Discord application"></p><h4 id="通過-dnf-刪除-discord" tabindex="-1">通過 DNF 刪除 Discord <a class="header-anchor" href="#通過-dnf-刪除-discord" aria-label="Permalink to “通過 DNF 刪除 Discord”">​</a></h4><p>如果你不想再使用 Discord，你可以從你的系統中刪除它。要做到這一點，在終端運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf remove discord</span></span></code></pre></div><p>這真的很簡單，不是嗎？還有一種簡單的安裝 Discord 的方法，那就是使用 Flatpak 軟件包。</p><h3 id="方法-2-通過-flatpak-安裝-discord" tabindex="-1">方法 2：通過 Flatpak 安裝 Discord <a class="header-anchor" href="#方法-2-通過-flatpak-安裝-discord" aria-label="Permalink to “方法 2：通過 Flatpak 安裝 Discord”">​</a></h3><p>Discord 可以使用 Flatpak 輕鬆安裝，因為它在 Fedora 中是默認可用的。</p><p>首先，你需要在 Fedora 中啓用 Flatpak 倉庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>flatpak remote-add --if-not-exists flathub https://flathub.org/repo/flathub.flatpakrepo</span></span></code></pre></div><p>接下來，通過這個命令安裝 Discord：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>flatpak install discord</span></span></code></pre></div><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/11/install-discord-flatpak.png?resize=800%2C545&amp;ssl=1" alt="Install Discord via Flatpak"></p><p>如果你想刪除 Discord，那麼只需運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>flatpak remove discord</span></span></code></pre></div><p>這就超級簡單了。如果你在 Fedora Linux 上安裝 Discord 需要任何幫助，請告訴我。</p><hr>',34)),t("p",null,[s[3]||(s[3]=i("via: ",-1)),o(a,{href:"https://itsfoss.com/install-discord-fedora/"},{default:e(()=>[...s[2]||(s[2]=[i("https://itsfoss.com/install-discord-fedora/",-1)])]),_:1})]),t("p",null,[s[8]||(s[8]=i("作者：",-1)),o(a,{href:"https://itsfoss.com/author/pranav/"},{default:e(()=>[...s[4]||(s[4]=[i("Pranav Krishna",-1)])]),_:1}),s[9]||(s[9]=i(" 選題：",-1)),o(a,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[5]||(s[5]=[i("lujun9972",-1)])]),_:1}),s[10]||(s[10]=i(" 譯者：",-1)),o(a,{href:"https://github.com/geekpi"},{default:e(()=>[...s[6]||(s[6]=[i("geekpi",-1)])]),_:1}),s[11]||(s[11]=i(" 校對：",-1)),o(a,{href:"https://github.com/wxy"},{default:e(()=>[...s[7]||(s[7]=[i("wxy",-1)])]),_:1})]),t("p",null,[s[14]||(s[14]=i("本文由 ",-1)),o(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[12]||(s[12]=[i("LCTT",-1)])]),_:1}),s[15]||(s[15]=i(" 原創編譯，",-1)),o(a,{href:"https://linux.cn/"},{default:e(()=>[...s[13]||(s[13]=[i("Linux中國",-1)])]),_:1}),s[16]||(s[16]=i(" 榮譽推出",-1))])])}const F=l(u,[["render",h]]);export{x as __pageData,F as default};
